<script setup>
import {ref, computed, watch, nextTick, onMounted, onBeforeUnmount} from 'vue';
import {state, api, notify} from '../store';
import Icon from './Icon.vue';
import AvatarCropper from './AvatarCropper.vue';

const copy = (en, id) => state.language === 'id' ? id : en;
const rows = ref([]), stats = ref(null), loading = ref(true), loadError = ref(''), feedback = ref(null);
const search = ref(''), role = ref(''), status = ref(''), sorting = ref('created_at:desc'), perPage = ref(10), page = ref(1), total = ref(0), lastPage = ref(1), mailDelivery = ref('');
const editor = ref(null), editorOpen = ref(false), editingUser = ref(null), form = ref({}), errors = ref({}), formError = ref(''), saving = ref(false);
const detailDialog = ref(null), detailOpen = ref(false), detail = ref(null), activity = ref([]), detailLoading = ref(false), detailError = ref('');
const confirmDialog = ref(null), confirmation = ref(null), confirmed = ref(false), actionBusy = ref(false), actionError = ref('');
const photoInput = ref(null), cropFile = ref(null), photo = ref(null), photoPreview = ref(''), photoRemoved = ref(false), photoError = ref(''), revealPassword = ref(false), revealConfirmation = ref(false), failedPhotos = ref({});
let searchTimer, disposed = false, requestRevision = 0, detailRevision = 0;
const isSelf = user => Number(user?.id) === Number(state.user?.id);
const editingSelf = computed(() => isSelf(editingUser.value));
const filtered = computed(() => Boolean(search.value.trim() || role.value || status.value));
const emailUnavailable = computed(() => ['log', 'array', 'null', ''].includes(mailDelivery.value));
const statCards = computed(() => [
    {key:'total', icon:'UsersRound', label:copy('Total users','Total pengguna')},
    {key:'superadmins', icon:'ShieldCheck', label:'Superadmin'},
    {key:'participants', icon:'GraduationCap', label:copy('Participants','Peserta')},
    {key:'active', icon:'CircleCheck', label:copy('Active users','Pengguna aktif')},
    {key:'inactive', icon:'ShieldX', label:copy('Inactive users','Pengguna nonaktif')},
]);
const participantFields = computed(() => [
    {key:'country', label:copy('Country of origin','Negara asal'), max:120, autocomplete:'country-name'},
    {key:'nationality', label:copy('Nationality','Kewarganegaraan'), max:120},
    {key:'native_language', label:copy('Native language','Bahasa ibu'), max:120},
    {key:'institution', label:copy('Institution','Institusi'), max:200, autocomplete:'organization'},
]);
const passwordRules = computed(() => [
    {met:Array.from(form.value.password || '').length >= 8, label:copy('At least 8 characters','Minimal 8 karakter')},
    {met:/\p{Ll}/u.test(form.value.password || '') && /\p{Lu}/u.test(form.value.password || ''), label:copy('Uppercase and lowercase letters','Huruf besar dan kecil')},
    {met:/\p{N}/u.test(form.value.password || ''), label:copy('A number','Angka')},
    {met:/[\p{Z}\p{S}\p{P}]/u.test(form.value.password || ''), label:copy('A symbol','Simbol')},
    {met:new TextEncoder().encode(form.value.password || '').length <= 72, label:copy('No more than 72 bytes','Tidak lebih dari 72 byte')},
]);
const photoSource = computed(() => photoRemoved.value ? '' : photoPreview.value || editingUser.value?.admin_avatar_url || editingUser.value?.avatar_url || '');
const formTitle = computed(() => editingUser.value ? copy('Edit user','Edit pengguna') : copy('Add new user','Tambah pengguna baru'));
const confirmTitle = computed(() => ({
    delete:copy('Delete this account?','Hapus akun ini?'),
    deactivate:copy('Deactivate this account?','Nonaktifkan akun ini?'),
    activate:copy('Activate this account?','Aktifkan akun ini?'),
    reset:copy('Reset this user’s password?','Atur ulang password pengguna ini?'),
    invite:copy('Resend account activation?','Kirim ulang aktivasi akun?'),
    role:copy('Confirm role change','Konfirmasi perubahan role'),
}[confirmation.value?.type] || ''));
const confirmButton = computed(() => ({
    delete:copy('Delete account','Hapus akun'), deactivate:copy('Deactivate account','Nonaktifkan akun'),
    activate:copy('Activate account','Aktifkan akun'), reset:copy('Send reset link','Kirim tautan reset'),
    invite:copy('Resend activation','Kirim ulang aktivasi'), role:copy('Confirm and save','Konfirmasi dan simpan'),
}[confirmation.value?.type] || copy('Confirm','Konfirmasi')));

function initials(name) { return String(name || 'INBAF').trim().split(/\s+/).filter(Boolean).slice(0, 2).map(part => Array.from(part)[0]).join('').toUpperCase(); }
function roleLabel(value) { return value === 'superadmin' ? 'Superadmin' : copy('Participant','Peserta'); }
function accountStatus(user) { return user?.deleted_at ? 'deleted' : user?.account_status || (user?.active ? 'active' : 'inactive'); }
function statusLabel(value) { return ({active:copy('Active','Aktif'), inactive:copy('Inactive','Nonaktif'), pending_activation:copy('Pending activation','Menunggu aktivasi'), deleted:copy('Deleted','Dihapus')})[value] || value; }
function formatDate(value, withTime = true) {
    if (!value) return copy('Never','Belum pernah');
    const date = new Date(value);
    if (Number.isNaN(date.getTime())) return '—';
    return new Intl.DateTimeFormat(state.language === 'id' ? 'id-ID' : 'en-GB', {dateStyle:'medium', ...(withTime ? {timeStyle:'short'} : {})}).format(date);
}
function number(value) { return new Intl.NumberFormat(state.language === 'id' ? 'id-ID' : 'en-GB').format(value || 0); }
function fieldError(field) { const value = errors.value[field]; return Array.isArray(value) ? value.join(' ') : value || ''; }
function clearError(field) { delete errors.value[field]; }
function selfReason() { return copy('Manage your own password in My Profile. Your role, status, and account deletion are protected here.','Kelola password Anda di Profil Saya. Role, status, dan penghapusan akun sendiri dilindungi di sini.'); }
function avatar(user) { return failedPhotos.value[user?.id] ? '' : user?.admin_avatar_url || user?.avatar_url || ''; }

async function load() {
    const revision = ++requestRevision;
    loading.value = true; loadError.value = '';
    const [sort, direction] = sorting.value.split(':');
    const query = new URLSearchParams({page:String(page.value), per_page:String(perPage.value), sort, direction});
    if (search.value.trim()) query.set('search', search.value.trim());
    if (role.value) query.set('role', role.value);
    if (status.value) query.set('status', status.value);
    try {
        const response = await api('/admin/users?' + query);
        if (disposed || revision !== requestRevision) return;
        rows.value = response.data || []; total.value = response.total || 0; lastPage.value = response.last_page || 1;
        stats.value = response.stats || stats.value; mailDelivery.value = response.mail_delivery || '';
        if (page.value > lastPage.value) { page.value = lastPage.value; return load(); }
    } catch (error) { if (!disposed && revision === requestRevision) loadError.value = error.message; }
    finally { if (!disposed && revision === requestRevision) loading.value = false; }
}
function changeFilters() { clearTimeout(searchTimer); page.value = 1; load(); }
function resetFilters() { search.value = ''; role.value = ''; status.value = ''; changeFilters(); }
function changePage(value) { if (loading.value || value < 1 || value > lastPage.value) return; page.value = value; load(); }
watch(search, () => { clearTimeout(searchTimer); searchTimer = setTimeout(changeFilters, 350); });
watch([role, status, sorting, perPage], changeFilters);

async function showDialog(reference) { await nextTick(); if (!disposed && reference.value && !reference.value.open) reference.value.showModal(); }
function clearPhoto() {
    if (photoPreview.value) URL.revokeObjectURL(photoPreview.value);
    photoPreview.value = ''; photo.value = null; photoRemoved.value = false; cropFile.value = null; photoError.value = '';
}
async function openEditor(user = null) {
    if (saving.value || actionBusy.value) return;
    clearPhoto(); errors.value = {}; formError.value = ''; editingUser.value = user;
    revealPassword.value = false; revealConfirmation.value = false;
    const profile = user?.profile || {};
    form.value = {name:user?.name || '', email:user?.email || '', role:user?.role || 'participant', status:user ? (accountStatus(user)==='pending_activation'||user.active ? 'active' : 'inactive') : 'active', phone:user?.phone || profile.phone || '', country:profile.country || '', nationality:profile.nationality || '', native_language:profile.native_language || '', institution:profile.institution || '', password_method:'activation', password:'', password_confirmation:''};
    if (detailOpen.value) closeDetail();
    editorOpen.value = true; await showDialog(editor);
    editor.value?.querySelector('#um-name')?.focus();
}
function closeEditor() {
    if (saving.value || actionBusy.value || cropFile.value) return;
    editor.value?.close(); editorOpen.value = false; clearPhoto(); form.value.password = ''; form.value.password_confirmation = '';
}
function choosePhoto(event) {
    const file = event.target.files?.[0]; event.target.value = ''; photoError.value = ''; clearError('photo');
    if (!file) return;
    if (!['image/jpeg','image/png','image/webp'].includes(file.type) || !/\.(jpe?g|png|webp)$/i.test(file.name)) { photoError.value = copy('Choose a JPG, PNG or WebP image.','Pilih gambar JPG, PNG, atau WebP.'); return; }
    if (file.size > 2 * 1024 * 1024) { photoError.value = copy('Choose a photo no larger than 2 MB.','Pilih foto berukuran maksimal 2 MB.'); return; }
    cropFile.value = file;
}
function usePhoto(file) {
    if (photoPreview.value) URL.revokeObjectURL(photoPreview.value);
    photo.value = file; photoPreview.value = URL.createObjectURL(file); photoRemoved.value = false; cropFile.value = null; photoError.value = '';
}
function removePhoto() { clearPhoto(); photoRemoved.value = true; }
async function focusFirstError() { await nextTick(); editor.value?.querySelector('[aria-invalid="true"]')?.focus(); }
function validateForm() {
    errors.value = {}; formError.value = '';
    if (!form.value.name.trim()) errors.value.name = [copy('Enter a full name.','Masukkan nama lengkap.')];
    if (!form.value.email.trim()) errors.value.email = [copy('Enter an email address.','Masukkan alamat email.')];
    else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(form.value.email.trim())) errors.value.email = [copy('Enter a valid email address.','Masukkan alamat email yang valid.')];
    if (!editingUser.value && form.value.password_method === 'manual') {
        if (!passwordRules.value.every(rule => rule.met)) errors.value.password = [copy('Use a password that meets every requirement below.','Gunakan password yang memenuhi semua syarat di bawah.')];
        if (!form.value.password_confirmation || form.value.password_confirmation !== form.value.password) errors.value.password_confirmation = [copy('The passwords must match.','Konfirmasi password harus sama.')];
    }
    if (Object.keys(errors.value).length) { formError.value = copy('Check the highlighted fields.','Periksa kolom yang ditandai.'); focusFirstError(); return false; }
    return true;
}
function submitForm() {
    if (saving.value || actionBusy.value || !validateForm()) return;
    if (editingUser.value && editingUser.value.role !== form.value.role) { openConfirmation('role', editingUser.value); return; }
    saveUser();
}
function mutationFeedback(response, fallback) {
    const delivery = response.delivery_status;
    if (delivery && typeof delivery === 'object' && !delivery.sent) {
        feedback.value = {tone:'warning', message:copy('The account was saved, but the email was not delivered. Configure email delivery, then resend the activation link from this user’s actions.','Akun tersimpan, tetapi email belum terkirim. Atur pengiriman email, lalu kirim ulang tautan aktivasi melalui aksi pengguna ini.') + (delivery.message ? ' ' + delivery.message : '')};
    } else { feedback.value = null; notify(response.message || fallback); }
}
async function saveUser(roleConfirmed = false) {
    if (saving.value) return;
    saving.value = true; formError.value = '';
    const body = new FormData();
    for (const field of ['name','email','role','status','phone','country','nationality','native_language','institution']) body.append(field, String(form.value[field] ?? '').trim());
    if (editingUser.value) body.append('_method', 'PUT');
    else {
        body.append('password_method', form.value.password_method);
        if (form.value.password_method === 'manual') { body.append('password', form.value.password); body.append('password_confirmation', form.value.password_confirmation); }
    }
    if (roleConfirmed) body.append('confirm_role_change', '1');
    if (photo.value) body.append('photo', photo.value);
    if (photoRemoved.value) body.append('remove_photo', '1');
    try {
        const response = await api('/admin/users' + (editingUser.value ? '/' + editingUser.value.id : ''), {method:'POST', body});
        if (disposed) return;
        if (isSelf(response.user)) state.user = {...state.user, ...response.user, avatar_url:response.user.admin_avatar_url || null};
        mutationFeedback(response, copy('User saved.','Pengguna tersimpan.'));
        saving.value = false; actionBusy.value = false; closeConfirmation(); closeEditor(); await load();
    } catch (error) {
        if (disposed) return;
        errors.value = error.data?.errors || {}; formError.value = error.data?.message || error.message;
        actionBusy.value = false; saving.value = false; closeConfirmation(); await focusFirstError();
    } finally { saving.value = false; }
}
async function openDetail(user) {
    const revision = ++detailRevision;
    detail.value = user; activity.value = []; detailError.value = ''; detailLoading.value = true; detailOpen.value = true;
    await showDialog(detailDialog);
    try {
        const response = await api('/admin/users/' + user.id);
        if (disposed || revision !== detailRevision || !detailOpen.value) return;
        detail.value = response.user || response;
        const entries = Array.isArray(response.activity) ? response.activity : response.activity?.data || [];
        activity.value = entries.map(item => ({...item, status:item.status || item.data?.status}));
    } catch (error) { if (!disposed && revision === detailRevision) detailError.value = error.message; }
    finally { if (!disposed && revision === detailRevision) detailLoading.value = false; }
}
function closeDetail() { detailRevision++; detailDialog.value?.close(); detailOpen.value = false; }
function activityLabel(item) {
    const event = item.event || item.action || item.type || '';
    const names = {
        'users.created':copy('Account created','Akun dibuat'), 'users.updated':copy('Profile updated','Profil diperbarui'),
        'users.role_changed':copy('Role changed','Role diubah'), 'users.activated':copy('Account activated','Akun diaktifkan'),
        'users.deactivated':copy('Account deactivated','Akun dinonaktifkan'), 'users.deleted':copy('Account deleted','Akun dihapus'),
        'users.credentials.invitation':copy('Activation email requested','Email aktivasi diminta'),
        'users.credentials.reset':copy('Password reset requested','Reset password diminta'),
        'account.activated':copy('Account activation completed','Aktivasi akun selesai'),
        'account.password_reset':copy('Password reset completed','Reset password selesai'),
        'account.password_changed':copy('Password changed','Password diubah'),
        'account.profile_updated':copy('Profile updated','Profil diperbarui'),
        'auth.login':copy('Signed in','Login'),
        'user.password_reset_requested':copy('Password reset requested','Reset password diminta'),
        'user.activation_sent':copy('Activation email requested','Email aktivasi diminta'),
    };
    return item.description || names[event] || String(event).replaceAll(/[._]/g, ' ') || copy('Account activity','Aktivitas akun');
}
async function openConfirmation(type, user) {
    if (saving.value || actionBusy.value) return;
    confirmation.value = {type, user}; confirmed.value = false; actionError.value = ''; await showDialog(confirmDialog);
}
function closeConfirmation() { if (actionBusy.value || saving.value) return; confirmDialog.value?.close(); confirmation.value = null; actionError.value = ''; }
async function performAction() {
    if (!confirmation.value || actionBusy.value || (confirmation.value.type === 'delete' && !confirmed.value)) return;
    const {type, user} = confirmation.value;
    if (type === 'role') { actionBusy.value = true; await saveUser(true); actionBusy.value = false; return; }
    actionBusy.value = true; actionError.value = '';
    const endpoint = {delete:'', activate:'/status', deactivate:'/status', reset:'/reset-password', invite:'/invite'}[type];
    const body = ['activate','deactivate'].includes(type) ? {status:type === 'activate' ? 'active' : 'inactive', confirmed:true} : type === 'delete' ? {confirmed:true} : {};
    try {
        const response = await api('/admin/users/' + user.id + endpoint, {method:type === 'delete' ? 'DELETE' : 'POST', body});
        if (disposed) return;
        mutationFeedback(response, copy('Action completed.','Tindakan selesai.'));
        actionBusy.value = false; closeConfirmation();
        if (detailOpen.value && Number(detail.value?.id) === Number(user.id)) await openDetail(response.user || user);
        await load();
    } catch (error) { if (!disposed) actionError.value = error.message; }
    finally { actionBusy.value = false; }
}
onMounted(load);
onBeforeUnmount(() => {
    disposed = true; requestRevision++; detailRevision++; clearTimeout(searchTimer); clearPhoto();
    [editor, detailDialog, confirmDialog].forEach(dialog => { if (dialog.value?.open) dialog.value.close(); });
});
</script>

<template>
<section class="user-management" aria-labelledby="um-title">
    <header class="um-heading">
        <div><span class="um-eyebrow"><Icon name="ShieldCheck" :size="18"/> {{copy('People & access','Pengguna & akses')}}</span><h1 id="um-title">{{copy('User Management','Manajemen Pengguna')}}</h1><p>{{copy('Manage the people behind every learning journey.','Kelola pengguna di setiap perjalanan belajar.')}}</p></div>
        <button class="button um-primary" @click="openEditor()"><Icon name="UserRoundPlus"/>{{copy('Add new user','Tambah pengguna')}}</button>
    </header>

    <div v-if="feedback" class="um-notice warning" role="status"><Icon name="CircleAlert"/><p>{{feedback.message}}</p><button class="icon-button" :aria-label="copy('Dismiss notice','Tutup pemberitahuan')" @click="feedback=null"><Icon name="X"/></button></div>
    <div class="um-stats" :aria-label="copy('User statistics, all accounts','Statistik seluruh pengguna')">
        <article v-for="card in statCards" :key="card.key" class="um-stat"><span class="um-stat-icon" :class="card.key"><Icon :name="card.icon" :size="22"/></span><div><span>{{card.label}}</span><strong>{{stats ? number(stats[card.key]) : '—'}}</strong></div></article>
    </div>
    <div v-if="!loading&&emailUnavailable" class="um-notice um-mail-note"><Icon name="Server"/><p><strong>{{copy('Email delivery in development','Pengiriman email dalam pengembangan')}}</strong> {{copy('Activation and reset emails need a configured mail service. You can create an account with a manual password now.','Email aktivasi dan reset memerlukan layanan email yang sudah diatur. Anda dapat membuat akun dengan password manual sekarang.')}}</p></div>

    <div class="um-directory">
        <div class="um-directory-heading"><div><h2>{{copy('User directory','Daftar pengguna')}}</h2><p>{{copy('Account details, access, and activity in one place.','Data akun, akses, dan aktivitas dalam satu tempat.')}}</p></div><span class="um-count" aria-live="polite">{{number(total)}} {{copy('users','pengguna')}}</span></div>
        <form class="um-filters" role="search" @submit.prevent="changeFilters">
            <div class="um-search"><label for="um-search">{{copy('Search users','Cari pengguna')}}</label><div><Icon name="Search" :size="20"/><input id="um-search" v-model="search" type="search" maxlength="200" :placeholder="copy('Search name or email','Cari nama atau email')" autocomplete="off"></div></div>
            <div><label for="um-role-filter">{{copy('Role','Role')}}</label><select id="um-role-filter" v-model="role"><option value="">{{copy('All roles','Semua role')}}</option><option value="superadmin">Superadmin</option><option value="participant">{{copy('Participant','Peserta')}}</option></select></div>
            <div><label for="um-status-filter">{{copy('Status','Status')}}</label><select id="um-status-filter" v-model="status"><option value="">{{copy('All statuses','Semua status')}}</option><option v-for="value in ['active','inactive','pending_activation','deleted']" :key="value" :value="value">{{statusLabel(value)}}</option></select></div>
            <div class="um-sort"><label for="um-sort">{{copy('Sort by','Urutkan')}}</label><select id="um-sort" v-model="sorting"><option value="created_at:desc">{{copy('Newest first','Terbaru')}}</option><option value="created_at:asc">{{copy('Oldest first','Terlama')}}</option><option value="name:asc">{{copy('Name A–Z','Nama A–Z')}}</option><option value="name:desc">{{copy('Name Z–A','Nama Z–A')}}</option><option value="email:asc">Email A–Z</option><option value="role:asc">{{copy('Role','Role')}}</option><option value="last_login_at:desc">{{copy('Last login','Login terakhir')}}</option></select></div>
            <button v-if="filtered" type="button" class="button secondary um-clear" @click="resetFilters"><Icon name="FilterX" :size="18"/>{{copy('Clear','Hapus filter')}}</button>
        </form>
        <div v-if="loadError" class="um-notice um-load-error" role="alert"><Icon name="CircleAlert"/><p>{{loadError}}</p><button class="button secondary" @click="load">{{copy('Try again','Coba lagi')}}</button></div>
        <p class="um-protection"><Icon name="LockKeyhole" :size="17"/>{{copy('Your own role, status, and deletion are protected. All administrative changes are recorded.','Role, status, dan penghapusan akun sendiri dilindungi. Semua perubahan administratif dicatat.')}}</p>
        <div v-if="loading" class="um-loading" role="status" aria-live="polite"><span class="loader"></span>{{copy('Loading users…','Memuat pengguna…')}}</div>
        <div v-else-if="!rows.length&&!loadError" class="um-empty"><span><Icon :name="filtered?'Search':'UsersRound'" :size="32"/></span><h3>{{filtered?copy('No matching users','Pengguna tidak ditemukan'):copy('Your directory starts here','Mulai daftar pengguna Anda')}}</h3><p>{{filtered?copy('Try a different name, email, role, or status.','Coba nama, email, role, atau status lain.'):copy('Add a participant or superadmin to get started.','Tambahkan peserta atau superadmin untuk memulai.')}}</p><button v-if="filtered" class="button secondary" @click="resetFilters">{{copy('Clear filters','Hapus filter')}}</button><button v-else class="button um-primary" @click="openEditor()"><Icon name="Plus"/>{{copy('Add new user','Tambah pengguna')}}</button></div>
        <div v-else-if="rows.length" class="um-table-region" role="region" :aria-label="copy('User directory table','Tabel daftar pengguna')" tabindex="0">
            <table class="um-table"><caption class="sr-only">{{copy('Users with roles, account status, registration dates, last login, and account actions.','Daftar pengguna, role, status akun, tanggal registrasi, login terakhir, dan aksi akun.')}}</caption><thead><tr><th scope="col">{{copy('No.','No.')}}</th><th scope="col">{{copy('User','Pengguna')}}</th><th scope="col">{{copy('Role','Role')}}</th><th scope="col">{{copy('Account status','Status akun')}}</th><th scope="col">{{copy('Registered','Terdaftar')}}</th><th scope="col">{{copy('Last login','Login terakhir')}}</th><th scope="col">{{copy('Actions','Aksi')}}</th></tr></thead>
                <tbody><tr v-for="(user,index) in rows" :key="user.id" :class="{'um-deleted':user.deleted_at}"><td class="um-row-number" :data-label="copy('No.','No.')">{{number((page-1)*perPage+index+1)}}</td><th scope="row" class="um-user-cell"><span class="um-avatar"><img v-if="avatar(user)" :src="avatar(user)" alt="" loading="lazy" @error="failedPhotos[user.id]=true"><span v-else aria-hidden="true">{{initials(user.name)}}</span></span><span class="um-user-text"><strong>{{user.name}} <span v-if="isSelf(user)" class="um-you">{{copy('You','Anda')}}</span></strong><span>{{user.email}}</span></span></th><td :data-label="copy('Role','Role')"><span class="um-role-badge" :class="user.role"><Icon :name="user.role==='superadmin'?'ShieldCheck':'GraduationCap'" :size="15"/>{{roleLabel(user.role)}}</span></td><td :data-label="copy('Account status','Status akun')"><span class="um-status-badge" :class="accountStatus(user)"><span></span>{{statusLabel(accountStatus(user))}}</span></td><td :data-label="copy('Registered','Terdaftar')" class="um-date">{{formatDate(user.created_at,false)}}</td><td :data-label="copy('Last login','Login terakhir')" class="um-date">{{formatDate(user.last_login_at)}}</td><td class="um-row-actions" :data-label="copy('Actions','Aksi')"><div>
                    <button class="icon-button" :aria-label="copy('View details for ','Lihat detail ')+user.name" :title="copy('View details','Lihat detail')" @click="openDetail(user)"><Icon name="Eye" :size="19"/></button>
                    <button class="icon-button" :disabled="Boolean(user.deleted_at)" :aria-label="copy('Edit ','Edit ')+user.name" :title="copy('Edit user','Edit pengguna')" @click="openEditor(user)"><Icon name="Pencil" :size="18"/></button>
                    <button v-if="accountStatus(user)==='pending_activation'" class="icon-button" :disabled="Boolean(user.deleted_at)||isSelf(user)" :aria-label="copy('Resend activation to ','Kirim ulang aktivasi kepada ')+user.name" :title="isSelf(user)?selfReason():copy('Resend activation','Kirim ulang aktivasi')" @click="openConfirmation('invite',user)"><Icon name="Send" :size="18"/></button>
                    <button v-else class="icon-button" :disabled="Boolean(user.deleted_at)||isSelf(user)||!user.active" :aria-label="copy('Reset password for ','Reset password ')+user.name" :title="isSelf(user)?selfReason():!user.active?copy('Activate this account before requesting a password reset.','Aktifkan akun ini sebelum meminta reset password.'):copy('Reset password','Reset password')" @click="openConfirmation('reset',user)"><Icon name="KeyRound" :size="18"/></button>
                    <button class="icon-button" :disabled="Boolean(user.deleted_at)||isSelf(user)||accountStatus(user)==='pending_activation'" :aria-label="(user.active?copy('Deactivate ','Nonaktifkan '):copy('Activate ','Aktifkan '))+user.name" :title="isSelf(user)?selfReason():accountStatus(user)==='pending_activation'?copy('Activation requires the email link. Use resend activation.','Aktivasi memerlukan tautan email. Gunakan kirim ulang aktivasi.'):(user.active?copy('Deactivate account','Nonaktifkan akun'):copy('Activate account','Aktifkan akun'))" @click="openConfirmation(user.active?'deactivate':'activate',user)"><Icon :name="user.active?'ShieldX':'CircleCheck'" :size="18"/></button>
                    <button class="icon-button um-delete-action" :disabled="Boolean(user.deleted_at)||isSelf(user)" :aria-label="copy('Delete ','Hapus ')+user.name" :title="isSelf(user)?selfReason():copy('Delete account','Hapus akun')" @click="openConfirmation('delete',user)"><Icon name="Trash2" :size="18"/></button>
                </div></td></tr></tbody>
            </table>
        </div>
        <footer class="um-pagination"><div><label for="um-per-page">{{copy('Rows per page','Baris per halaman')}}</label><select id="um-per-page" v-model.number="perPage"><option :value="10">10</option><option :value="25">25</option><option :value="50">50</option><option :value="100">100</option></select></div><p aria-live="polite">{{total?number((page-1)*perPage+1):'0'}}–{{number(Math.min(page*perPage,total))}} {{copy('of','dari')}} {{number(total)}}</p><nav :aria-label="copy('User pagination','Navigasi halaman pengguna')"><button class="icon-button" :disabled="page<=1||loading" :aria-label="copy('Previous page','Halaman sebelumnya')" @click="changePage(page-1)"><Icon name="ChevronLeft"/></button><span>{{number(page)}} / {{number(lastPage)}}</span><button class="icon-button" :disabled="page>=lastPage||loading" :aria-label="copy('Next page','Halaman berikutnya')" @click="changePage(page+1)"><Icon name="ChevronRight"/></button></nav></footer>
    </div>

    <Teleport to="body">
        <dialog ref="editor" class="um-dialog um-editor" aria-labelledby="um-editor-title" aria-describedby="um-editor-description" @cancel.prevent="closeEditor">
            <template v-if="editorOpen"><header class="um-dialog-header"><div><span class="um-dialog-icon"><Icon :name="editingUser?'Pencil':'UserRoundPlus'"/></span><h2 id="um-editor-title">{{formTitle}}</h2><p id="um-editor-description">{{editingUser?copy('Update account details and access securely.','Perbarui data dan akses akun dengan aman.'):copy('Give a participant or administrator access to INBAF.','Berikan akses INBAF kepada peserta atau administrator.')}}</p></div><button type="button" class="icon-button" :disabled="saving||actionBusy" :aria-label="copy('Close user form','Tutup formulir pengguna')" @click="closeEditor"><Icon name="X"/></button></header>
                <form novalidate @submit.prevent="submitForm">
                    <div v-if="formError" class="um-notice um-form-error" role="alert"><Icon name="CircleAlert"/><p>{{formError}}</p></div>
                    <fieldset :disabled="saving||actionBusy"><legend class="sr-only">{{copy('Account details','Data akun')}}</legend>
                        <div class="um-photo-field"><span class="um-avatar um-form-avatar"><img v-if="photoSource" :src="photoSource" alt="" @error="photoError=copy('Photo preview is unavailable. You can choose a new photo.','Pratinjau foto tidak tersedia. Anda dapat memilih foto baru.')"><span v-else aria-hidden="true">{{initials(form.name)}}</span></span><div><strong>{{copy('Profile photo','Foto profil')}}</strong><p>{{copy('Optional · JPG, PNG or WebP · Max. 2 MB','Opsional · JPG, PNG, atau WebP · Maks. 2 MB')}}</p><div class="um-photo-actions"><button type="button" class="button secondary" @click="photoInput?.click()"><Icon name="Upload" :size="17"/>{{copy('Choose photo','Pilih foto')}}</button><button v-if="photoSource" type="button" class="text-button um-remove-photo" @click="removePhoto">{{copy('Remove','Hapus')}}</button></div></div><input ref="photoInput" class="um-file-input" type="file" accept="image/jpeg,image/png,image/webp" :aria-label="copy('Profile photo file','File foto profil')" @change="choosePhoto"></div>
                        <p v-if="photoError||fieldError('photo')" class="um-field-error" role="alert">{{photoError||fieldError('photo')}}</p>
                        <div class="um-form-grid">
                            <div class="um-field"><label for="um-name">{{copy('Full name','Nama lengkap')}} <span aria-hidden="true">*</span></label><input id="um-name" v-model="form.name" name="name" required maxlength="200" autocomplete="name" :aria-invalid="Boolean(fieldError('name'))" :aria-describedby="fieldError('name')?'um-error-name':undefined" @input="clearError('name')"><p v-if="fieldError('name')" id="um-error-name" class="um-field-error">{{fieldError('name')}}</p></div>
                            <div class="um-field"><label for="um-email">{{copy('Email address','Alamat email')}} <span aria-hidden="true">*</span></label><input id="um-email" v-model="form.email" name="email" type="email" required maxlength="254" autocomplete="email" :aria-invalid="Boolean(fieldError('email'))" :aria-describedby="fieldError('email')?'um-error-email':undefined" @input="clearError('email')"><p v-if="fieldError('email')" id="um-error-email" class="um-field-error">{{fieldError('email')}}</p></div>
                            <div class="um-field"><label for="um-role">{{copy('Role','Role')}} <span aria-hidden="true">*</span></label><select id="um-role" v-model="form.role" name="role" :disabled="editingSelf" :aria-invalid="Boolean(fieldError('role'))" :aria-describedby="editingSelf?'um-self-help':fieldError('role')?'um-error-role':undefined" @change="clearError('role')"><option value="participant">{{copy('Participant','Peserta')}}</option><option value="superadmin">Superadmin</option></select><p v-if="fieldError('role')" id="um-error-role" class="um-field-error">{{fieldError('role')}}</p></div>
                            <div class="um-field"><label for="um-status">{{copy('Account status','Status akun')}} <span aria-hidden="true">*</span></label><select id="um-status" v-model="form.status" name="status" :disabled="editingSelf" :aria-invalid="Boolean(fieldError('status'))" :aria-describedby="editingSelf?'um-self-help':fieldError('status')?'um-error-status':undefined" @change="clearError('status')"><option value="active">{{copy('Active','Aktif')}}</option><option value="inactive">{{copy('Inactive','Nonaktif')}}</option></select><p v-if="fieldError('status')" id="um-error-status" class="um-field-error">{{fieldError('status')}}</p></div>
                            <p v-if="editingSelf" id="um-self-help" class="um-field-help um-span-all">{{selfReason()}}</p>
                            <div class="um-field um-span-all"><label for="um-phone">{{copy('Phone number','Nomor telepon')}} <span class="um-optional">{{copy('(optional)','(opsional)')}}</span></label><input id="um-phone" v-model="form.phone" name="phone" type="tel" autocomplete="tel" maxlength="32" :aria-invalid="Boolean(fieldError('phone'))" :aria-describedby="fieldError('phone')?'um-error-phone':undefined" @input="clearError('phone')"><p v-if="fieldError('phone')" id="um-error-phone" class="um-field-error">{{fieldError('phone')}}</p></div>
                        </div>
                        <div v-if="form.role==='participant'" class="um-form-section"><h3><Icon name="GraduationCap" :size="21"/>{{copy('Participant profile','Profil peserta')}}</h3><p>{{copy('Optional details to support the participant’s learning journey.','Data opsional untuk mendukung perjalanan belajar peserta.')}}</p><div class="um-form-grid"><div v-for="field in participantFields" :key="field.key" class="um-field"><label :for="'um-'+field.key">{{field.label}}</label><input :id="'um-'+field.key" v-model="form[field.key]" :name="field.key" :maxlength="field.max" :autocomplete="field.autocomplete" :aria-invalid="Boolean(fieldError(field.key))" :aria-describedby="fieldError(field.key)?'um-error-'+field.key:undefined" @input="clearError(field.key)"><p v-if="fieldError(field.key)" :id="'um-error-'+field.key" class="um-field-error">{{fieldError(field.key)}}</p></div></div></div>
                        <div v-else class="um-notice um-role-note"><Icon name="ShieldCheck"/><p>{{copy('Superadmins can manage users, assessments, scoring, and platform settings. Assign this role only to authorized staff.','Superadmin dapat mengelola pengguna, asesmen, penilaian, dan pengaturan platform. Berikan role ini hanya kepada staf berwenang.')}}</p></div>
                        <div v-if="!editingUser" class="um-form-section"><h3><Icon name="LockKeyhole" :size="21"/>{{copy('Initial account access','Akses awal akun')}}</h3><div class="um-field um-method-field"><label for="um-password-method">{{copy('Password setup','Pengaturan password')}}</label><select id="um-password-method" v-model="form.password_method" name="password_method" :aria-invalid="Boolean(fieldError('password_method'))" :aria-describedby="fieldError('password_method')?'um-error-password-method':undefined" @change="clearError('password_method')"><option value="activation">{{copy('Email activation — recommended','Aktivasi email — direkomendasikan')}}</option><option value="manual">{{copy('Set a manual password','Buat password manual')}}</option></select><p v-if="fieldError('password_method')" id="um-error-password-method" class="um-field-error">{{fieldError('password_method')}}</p></div>
                            <div v-if="form.password_method==='activation'" class="um-notice" :class="{'warning':emailUnavailable}"><Icon :name="emailUnavailable?'CircleAlert':'Send'"/><p>{{emailUnavailable?copy('Email delivery is not configured for this environment. The account will remain pending activation until an activation email can be delivered. Choose a manual password to give access now.','Pengiriman email belum diatur untuk lingkungan ini. Akun akan menunggu aktivasi hingga email aktivasi dapat dikirim. Pilih password manual untuk memberikan akses sekarang.'):copy('The user receives a temporary activation link and chooses their own password. No password is sent by email.','Pengguna menerima tautan aktivasi sementara dan membuat password sendiri. Password tidak dikirim melalui email.')}}</p></div>
                            <template v-else><div class="um-form-grid"><div class="um-field"><label for="um-password">{{copy('Initial password','Password awal')}} <span aria-hidden="true">*</span></label><div class="um-password-input"><input id="um-password" v-model="form.password" name="password" :type="revealPassword?'text':'password'" autocomplete="new-password" required :aria-invalid="Boolean(fieldError('password'))" :aria-describedby="fieldError('password')?'um-error-password um-password-rules':'um-password-rules'" @input="clearError('password')"><button type="button" class="icon-button" :aria-label="revealPassword?copy('Hide initial password','Sembunyikan password awal'):copy('Show initial password','Tampilkan password awal')" :aria-pressed="revealPassword" @click="revealPassword=!revealPassword"><Icon :name="revealPassword?'EyeOff':'Eye'" :size="20"/></button></div><p v-if="fieldError('password')" id="um-error-password" class="um-field-error">{{fieldError('password')}}</p></div><div class="um-field"><label for="um-password-confirmation">{{copy('Confirm password','Konfirmasi password')}} <span aria-hidden="true">*</span></label><div class="um-password-input"><input id="um-password-confirmation" v-model="form.password_confirmation" name="password_confirmation" :type="revealConfirmation?'text':'password'" autocomplete="new-password" required :aria-invalid="Boolean(fieldError('password_confirmation'))" :aria-describedby="fieldError('password_confirmation')?'um-error-password-confirmation':undefined" @input="clearError('password_confirmation')"><button type="button" class="icon-button" :aria-label="revealConfirmation?copy('Hide password confirmation','Sembunyikan konfirmasi password'):copy('Show password confirmation','Tampilkan konfirmasi password')" :aria-pressed="revealConfirmation" @click="revealConfirmation=!revealConfirmation"><Icon :name="revealConfirmation?'EyeOff':'Eye'" :size="20"/></button></div><p v-if="fieldError('password_confirmation')" id="um-error-password-confirmation" class="um-field-error">{{fieldError('password_confirmation')}}</p></div></div><ul id="um-password-rules" class="um-password-rules"><li v-for="rule in passwordRules" :key="rule.label" :class="{met:rule.met}"><Icon :name="rule.met?'CircleCheck':'Circle'" :size="16"/><span>{{rule.label}}</span></li></ul><p class="um-field-help">{{copy('The user must change this password at their first login. Share the initial password securely.','Pengguna wajib mengganti password saat login pertama. Sampaikan password awal dengan aman.')}}</p></template>
                        </div>
                        <div v-if="editingUser" class="um-notice um-history-note"><Icon name="Archive"/><p>{{copy('Existing test results and certificates are preserved when account details or roles change.','Hasil ujian dan sertifikat yang sudah ada tetap tersimpan saat data atau role akun berubah.')}}</p></div>
                    </fieldset>
                    <footer class="um-dialog-footer"><button type="button" class="button secondary" :disabled="saving||actionBusy" @click="closeEditor">{{copy('Cancel','Batal')}}</button><button type="submit" class="button um-primary" :disabled="saving||actionBusy"><span v-if="saving" class="loader"></span><Icon v-else name="Check" :size="19"/>{{saving?copy('Saving…','Menyimpan…'):editingUser?copy('Save changes','Simpan perubahan'):copy('Create account','Buat akun')}}</button></footer>
                </form>
            </template>
        </dialog>

        <dialog ref="detailDialog" class="um-dialog um-detail" aria-labelledby="um-detail-title" @cancel.prevent="closeDetail"><template v-if="detailOpen&&detail"><header class="um-dialog-header"><div><span class="um-eyebrow">{{copy('Account overview','Ringkasan akun')}}</span><h2 id="um-detail-title">{{copy('User details','Detail pengguna')}}</h2></div><button class="icon-button" :aria-label="copy('Close user details','Tutup detail pengguna')" @click="closeDetail"><Icon name="X"/></button></header><div class="um-detail-person"><span class="um-avatar um-detail-avatar"><img v-if="avatar(detail)" :src="avatar(detail)" alt="" @error="failedPhotos[detail.id]=true"><span v-else aria-hidden="true">{{initials(detail.name)}}</span></span><div><h3>{{detail.name}}</h3><p>{{detail.email}}</p><div class="um-detail-badges"><span class="um-role-badge" :class="detail.role">{{roleLabel(detail.role)}}</span><span class="um-status-badge" :class="accountStatus(detail)"><span></span>{{statusLabel(accountStatus(detail))}}</span></div></div></div>
            <div v-if="detailLoading" class="um-detail-loading" role="status"><span class="loader"></span>{{copy('Loading account activity…','Memuat aktivitas akun…')}}</div><div v-if="detailError" class="um-notice um-form-error" role="alert"><Icon name="CircleAlert"/><p>{{detailError}}</p><button class="button secondary" @click="openDetail(detail)">{{copy('Try again','Coba lagi')}}</button></div>
            <dl class="um-detail-grid"><div><dt>{{copy('Registered','Terdaftar')}}</dt><dd>{{formatDate(detail.created_at)}}</dd></div><div><dt>{{copy('Last login','Login terakhir')}}</dt><dd>{{formatDate(detail.last_login_at)}}</dd></div><div><dt>{{copy('Phone number','Nomor telepon')}}</dt><dd>{{detail.phone||detail.profile?.phone||copy('Not provided','Belum diisi')}}</dd></div><div><dt>{{copy('Password change required','Wajib ganti password')}}</dt><dd>{{detail.must_change_password?copy('At next login','Saat login berikutnya'):copy('No','Tidak')}}</dd></div><template v-if="detail.role==='participant'"><div v-for="field in participantFields" :key="field.key"><dt>{{field.label}}</dt><dd>{{detail.profile?.[field.key]||copy('Not provided','Belum diisi')}}</dd></div></template><div><dt>{{copy('Test attempts','Percobaan ujian')}}</dt><dd>{{number(detail.attempts_count)}}</dd></div><div><dt>{{copy('Certificates','Sertifikat')}}</dt><dd>{{number(detail.certificates_count)}}</dd></div></dl>
            <section class="um-activity" aria-labelledby="um-activity-title"><h3 id="um-activity-title"><Icon name="Clock3" :size="21"/>{{copy('Recent account activity','Aktivitas akun terbaru')}}</h3><p class="um-field-help">{{copy('Administrative actions recorded for this account.','Tindakan administratif yang dicatat untuk akun ini.')}}</p><ol v-if="activity.length"><li v-for="(item,index) in activity" :key="item.id||index"><span class="um-activity-dot"><Icon name="Check" :size="15"/></span><div><strong>{{activityLabel(item)}}</strong><p>{{item.actor?.name||item.actor_name||item.user?.name||copy('System','Sistem')}}<span v-if="item.status"> · {{item.status==='success'?copy('Success','Berhasil'):item.status}}</span></p><time :datetime="item.created_at">{{formatDate(item.created_at)}}</time></div></li></ol><p v-else-if="!detailLoading&&!detailError" class="um-no-activity">{{copy('No administrative activity recorded yet.','Belum ada aktivitas administratif yang dicatat.')}}</p></section><footer class="um-dialog-footer"><button class="button secondary" @click="closeDetail">{{copy('Close','Tutup')}}</button><button v-if="!detail.deleted_at" class="button um-primary" :disabled="detailLoading" @click="openEditor(detail)"><Icon name="Pencil" :size="18"/>{{copy('Edit user','Edit pengguna')}}</button></footer></template></dialog>

        <dialog ref="confirmDialog" class="um-dialog um-confirm" aria-labelledby="um-confirm-title" aria-describedby="um-confirm-description" @cancel.prevent="closeConfirmation"><template v-if="confirmation"><header class="um-dialog-header"><div><span class="um-dialog-icon" :class="{'um-danger-icon':['delete','deactivate'].includes(confirmation.type)}"><Icon :name="confirmation.type==='delete'?'Trash2':confirmation.type==='role'?'ShieldCheck':confirmation.type==='reset'?'KeyRound':confirmation.type==='invite'?'Send':'CircleAlert'"/></span><h2 id="um-confirm-title">{{confirmTitle}}</h2></div><button class="icon-button" :disabled="actionBusy||saving" :aria-label="copy('Close confirmation','Tutup konfirmasi')" @click="closeConfirmation"><Icon name="X"/></button></header><div class="um-confirm-person"><strong>{{confirmation.user.name}}</strong><span>{{confirmation.user.email}}</span></div><div id="um-confirm-description">
            <template v-if="confirmation.type==='delete'"><p>{{copy('The account will be removed from the active directory and will no longer be able to sign in. Its test history and certificates will be retained.','Akun akan dihapus dari daftar aktif dan tidak dapat login lagi. Riwayat ujian dan sertifikat tetap tersimpan.')}}</p><p v-if="confirmation.user.attempts_count||confirmation.user.certificates_count" class="um-history-warning"><Icon name="Archive" :size="20"/>{{copy('This user has recorded assessment history.','Pengguna ini memiliki riwayat asesmen.')}} {{number(confirmation.user.attempts_count)}} {{copy('test attempts','percobaan ujian')}} · {{number(confirmation.user.certificates_count)}} {{copy('certificates','sertifikat')}}.</p></template>
            <p v-else-if="confirmation.type==='deactivate'">{{copy('This user will be signed out and cannot sign in again until the account is active. Their account data, test results, and certificates will remain stored.','Pengguna akan dikeluarkan dari sesi dan tidak dapat login hingga akun diaktifkan kembali. Data akun, hasil ujian, dan sertifikat tetap tersimpan.')}}</p>
            <p v-else-if="confirmation.type==='activate'">{{copy('This user will be able to sign in when their account activation and password requirements have been completed.','Pengguna dapat login setelah memenuhi persyaratan aktivasi akun dan password.')}}</p>
            <p v-else-if="confirmation.type==='reset'">{{copy('A temporary reset link will be sent to this email address so the user can choose a new password. Their existing password is never displayed.','Tautan reset sementara akan dikirim ke alamat email ini agar pengguna dapat membuat password baru. Password lama tidak pernah ditampilkan.')}}</p>
            <p v-else-if="confirmation.type==='invite'">{{copy('A new temporary activation link will be sent to this email address. The user chooses their own password.','Tautan aktivasi sementara yang baru akan dikirim ke alamat email ini. Pengguna membuat password sendiri.')}}</p>
            <template v-else-if="confirmation.type==='role'"><p>{{copy('You are changing this user’s role and access permissions. Existing test results and certificates will be preserved.','Anda akan mengubah role dan hak akses pengguna ini. Hasil ujian dan sertifikat yang sudah ada tetap tersimpan.')}}</p><div class="um-role-change"><span>{{roleLabel(editingUser.role)}}</span><Icon name="ArrowRight" :size="20"/><strong>{{roleLabel(form.role)}}</strong></div><p v-if="form.role==='superadmin'">{{copy('This grants full administrative access to users, assessments, and platform settings.','Perubahan ini memberikan akses administratif penuh ke pengguna, asesmen, dan pengaturan platform.')}}</p></template>
        </div><div v-if="['reset','invite'].includes(confirmation.type)&&emailUnavailable" class="um-notice warning"><Icon name="CircleAlert"/><p>{{copy('Email delivery is not configured. This link cannot be delivered until the mail service is ready.','Pengiriman email belum diatur. Tautan ini belum dapat dikirim hingga layanan email siap.')}}</p></div><label v-if="confirmation.type==='delete'" class="um-delete-confirmation"><input v-model="confirmed" type="checkbox" :disabled="actionBusy"><span>{{copy('I confirm the removal of this account.','Saya mengonfirmasi penghapusan akun ini.')}}</span></label><div v-if="actionError" class="um-notice um-form-error" role="alert"><Icon name="CircleAlert"/><p>{{actionError}}</p></div><footer class="um-dialog-footer"><button class="button secondary" :disabled="actionBusy||saving" @click="closeConfirmation">{{copy('Cancel','Batal')}}</button><button class="button" :class="['delete','deactivate'].includes(confirmation.type)?'danger':'um-primary'" :disabled="actionBusy||saving||(confirmation.type==='delete'&&!confirmed)" @click="performAction"><span v-if="actionBusy||saving" class="loader"></span>{{actionBusy||saving?copy('Processing…','Memproses…'):confirmButton}}</button></footer></template></dialog>
    </Teleport>
    <AvatarCropper v-if="cropFile" :file="cropFile" @save="usePhoto" @cancel="cropFile=null"/>
</section>
</template>

